  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C18"],
      "claim": "Ketoconazole, a close structural analogue sharing the dioxolane-dichlorophenyl-azole core, has a mean oral bioavailability of approximately 75% in healthy volunteers, supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C42"],
      "claim": "Posaconazole, a structurally related triazole antifungal with the same triazolone/piperazine/aryl ether motif, has an absolute oral bioavailability of around 50% for the delayed-release tablet in healthy volunteers, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "Voriconazole, another azole antifungal, has a mean absolute oral bioavailability of approximately 96%, supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C24"],
      "claim": "Genaconazole, a triazole antifungal, showed an absolute oral bioavailability of 100% in healthy male volunteers, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Venetoclax, a structurally unrelated BCL-2 inhibitor, has an absolute oral bioavailability of 5.4% under fasting conditions, but its very low structural similarity and different chemical class make this contradictory evidence weakly transferable.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is itraconazole, a triazole antifungal structurally very close to ketoconazole and posaconazole. The closest analogues and other azoles consistently show oral bioavailability well above the 20% threshold (ketoconazole ~75%, posaconazole tablet ~50%, voriconazole ~96%, genaconazole ~100%). The only low-F evidence comes from a structurally unrelated drug and a formulation-dependent posaconazole suspension, which do not override the strong azole support. Therefore predict high.",
  "evidence_gaps": [
    "No direct absolute bioavailability record for itraconazole itself is present in the supplied evidence; extrapolation relies on close analogues.",
    "Posaconazole suspension data show formulation-dependent F that can fall below 20% in some pediatric populations, but the query is a molecular property rather than a specific formulation."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

